import type { NextginExport } from './export.js'

export const CF_COMPAT_DATE = '2026-11-01'
export const CF_INTERNAL_ORIGIN = 'http://nextgin-backend.internal'
export const CF_BACKEND_BINDING = 'NEXTGIN_BACKEND'
export const CF_GENERATED_MARKER =
  '// generated by nextgin — edits are overwritten; remove this line to take ownership'

export interface BackendWranglerConfig {
  name: string
  main: string
  compatibility_date: string
  workers_dev: boolean
  preview_urls: boolean
  routes?: Array<{
    pattern: string
    custom_domain: boolean
  }>
  triggers: {
    crons: string[]
  }
}

export interface WebWranglerConfig {
  name: string
  main: string
  compatibility_date: string
  compatibility_flags: string[]
  assets: {
    directory: string
    binding: string
  }
  services: Array<{
    binding: string
    service: string
  }>
  vars: {
    NEXTGIN_INTERNAL_URL: string
  }
}

/**
 * Normalizes an arbitrary app name into a valid Cloudflare Worker name
 * (lowercase `[a-z0-9-]`, max 54 chars so `-backend` fits within 63 chars).
 */
export function workerName(raw: string): string {
  const normalized = raw
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 54)
    .replace(/-+$/, '')
  if (!normalized) {
    throw new Error(`nextgin: invalid worker name "${raw}"`)
  }
  return normalized
}

/**
 * Builds the `wrangler.jsonc` config object for the Go/WASM backend worker.
 */
export function generateBackendWrangler(
  exp: NextginExport,
  opts: { name: string; customDomain?: string },
): BackendWranglerConfig {
  const seen = new Set<string>()
  const crons: string[] = []
  for (const cron of exp.crons) {
    if (!seen.has(cron.cloudflare)) {
      seen.add(cron.cloudflare)
      crons.push(cron.cloudflare)
    }
  }

  return {
    name: `${opts.name}-backend`,
    main: 'build/worker.mjs',
    compatibility_date: CF_COMPAT_DATE,
    workers_dev: false,
    preview_urls: false,
    ...(opts.customDomain
      ? { routes: [{ pattern: opts.customDomain, custom_domain: true }] }
      : {}),
    triggers: {
      crons,
    },
  }
}

/**
 * Builds the `wrangler.jsonc` config object for the OpenNext web worker.
 */
export function generateWebWrangler(opts: { name: string }): WebWranglerConfig {
  return {
    name: opts.name,
    main: 'nextgin-worker.mjs',
    compatibility_date: CF_COMPAT_DATE,
    compatibility_flags: ['nodejs_compat'],
    assets: {
      directory: '.open-next/assets',
      binding: 'ASSETS',
    },
    services: [
      { binding: 'WORKER_SELF_REFERENCE', service: opts.name },
      { binding: CF_BACKEND_BINDING, service: `${opts.name}-backend` },
    ],
    vars: {
      NEXTGIN_INTERNAL_URL: CF_INTERNAL_ORIGIN,
    },
  }
}

/**
 * Serializes a Wrangler config object as JSONC with the generated-file marker.
 */
export function serializeWrangler(cfg: object): string {
  return CF_GENERATED_MARKER + '\n' + JSON.stringify(cfg, null, 2) + '\n'
}

/**
 * Generates `nextgin-worker.mjs` that wraps OpenNext's worker to route Go
 * prefixes and `NEXTGIN_INTERNAL_URL` fetches through the backend service binding.
 */
export function generateWebWorker(prefixes: string[]): string {
  return `${CF_GENERATED_MARKER}
import handler from "./.open-next/worker.js";
export * from "./.open-next/worker.js";

const GO_PREFIXES = ${JSON.stringify(prefixes)};
const INTERNAL_ORIGIN = ${JSON.stringify(CF_INTERNAL_ORIGIN)};
let backend;

const originalFetch = globalThis.fetch;
globalThis.fetch = function (input, init) {
  const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
  if (backend && (url === INTERNAL_ORIGIN || url.startsWith(INTERNAL_ORIGIN + "/"))) {
    return backend.fetch(input, init);
  }
  return originalFetch(input, init);
};

function isGoPath(pathname) {
  return GO_PREFIXES.some((p) => pathname === "/" + p || pathname.startsWith("/" + p + "/"));
}

export default {
  async fetch(request, env, ctx) {
    backend = env.${CF_BACKEND_BINDING};
    if (isGoPath(new URL(request.url).pathname)) {
      return env.${CF_BACKEND_BINDING}.fetch(request);
    }
    return handler.fetch(request, env, ctx);
  },
};
`
}

/**
 * Returns true if a file does not exist or still starts with the generated-file marker.
 */
export function canOverwrite(existing: string | undefined): boolean {
  if (existing === undefined) return true
  const firstLine = existing.split(/\r?\n/, 1)[0]
  return firstLine === CF_GENERATED_MARKER
}
